pragma solidity 0.8.36;
contract C { int constant a = 7; int constant b = 3; int constant c = a / b; int constant d = (-a) / b; function f() external pure returns (uint, uint, uint) { uint[c] memory x; uint[-d] memory y; uint[-d] memory z = [uint(1), uint(2)]; return (x.length, y.length, z[0]); } }
